import{_ as o,o as t,c as a,a3 as s}from"./chunks/framework.B9qR_F1m.js";const u=JSON.parse('{"title":"Privileges","description":"","frontmatter":{},"headers":[],"relativePath":"privileges.md","filePath":"privileges.md"}'),d={name:"privileges.md"};function n(r,e,i,c,p,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="privileges" tabindex="-1">Privileges <a class="header-anchor" href="#privileges" aria-label="Permalink to &quot;Privileges&quot;">​</a></h1><p>ripeat asks for admin rights only for the steps that need them, and tells you before it changes anything.</p><h2 id="scope-per-step" tabindex="-1">Scope per step <a class="header-anchor" href="#scope-per-step" aria-label="Permalink to &quot;Scope per step&quot;">​</a></h2><p>Each install option has a <code>scope</code> (<a href="./recipes">Recipes</a>): <code>user</code> needs no admin rights, <code>system</code> (the default) does. The plan shows it as <code>user</code> or <code>admin</code>.</p><h2 id="one-up-front-request" tabindex="-1">One up-front request <a class="header-anchor" href="#one-up-front-request" aria-label="Permalink to &quot;One up-front request&quot;">​</a></h2><p>Before the first change, <code>install</code> and <code>upgrade</code> list the steps that need admin rights (&quot;Administrator rights are needed for: ...&quot;) and, on Linux and macOS when you are not root, run <code>sudo -v</code> once so the password prompt comes first. If that fails nothing has been changed. Steps already satisfied (managed or already on the machine) are not counted. <code>policy --apply</code> does the same.</p><p><code>uninstall</code> and <code>rollback</code> do not ask up front; <code>sudo</code> may prompt in the middle. <code>sudo</code> remembers the password for its own timeout (usually 15 minutes), so a long run can still prompt again.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Homebrew refuses to run as root, so <code>brew</code> and <code>brew_cask</code> steps never need admin rights and ripeat never runs them through <code>sudo</code>. A cask whose installer needs a password (some <code>.pkg</code> apps) asks for it itself, in the middle of the run.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>A process cannot gain admin rights part-way on Windows, so ripeat cannot elevate itself. <code>shell</code> steps with <code>scope: system</code> are refused up front when the terminal is not elevated (nothing changes). <code>winget</code> installers ask for UAC themselves. <code>choco</code> needs an elevated terminal, and ripeat does not check that up front yet. <code>policy --apply</code> requires an elevated terminal.</p><h2 id="scope-user-system" tabindex="-1"><code>--scope user|system</code> <a class="header-anchor" href="#scope-user-system" aria-label="Permalink to &quot;`--scope user|system`&quot;">​</a></h2><p>On <code>install</code> and <code>plan</code>, limits which options may be chosen:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Chooses only options that</th></tr></thead><tbody><tr><td><code>--scope user</code></td><td>need no admin rights (<code>scoop</code>, <code>github_release</code>, <code>winget</code> with <code>scope: user</code>, ...)</td></tr><tr><td><code>--scope system</code></td><td>need admin rights</td></tr><tr><td>(none)</td><td>any; the first usable option wins</td></tr></tbody></table><p>If a tool has no option in that scope, the plan fails before anything changes and names the methods the recipe has. For example, <code>ripeat plan git --scope user</code> on Linux fails because <code>apt</code>, <code>dnf</code> and <code>pacman</code> all need admin rights.</p>',15)])])}const m=o(d,[["render",n]]);export{u as __pageData,m as default};
